        "Do nothing",
        "",
        "Comment",
        "-------- \",~Comment Text,\" --------",
        "",
        "Custom Script",
        "\"Custom script:   \",~Script Code",
        "Enter one line of script code.  Example: 'call my_func(udg_my_var)'",
        "Wait",
        "Wait \",~Time,\" seconds",
        "The duration of this wait is specified in real-time seconds.",
        "Wait (Game-Time)",
        "Wait \",~Time,\" game-time seconds",
        "The duration of this wait is specified in game-time seconds.  This is a polled wait, so it may last slightly longer than requested.",
        "Wait For Condition",
        "Wait until \",~Condition,\", checking every \",~Interval,\" seconds",
        "",
        "Wait For Sound",
        "Wait for \",~Sound,\" to be \",~Time,\" seconds from finished playing",
        "This action only waits if the sound is currently playing.  If the sound has not yet started, or has already finished, this action does nothing.",
        "Set Variable",
        "\"Set \",~Variable,\" = \",~Value",
        "",
        "Skip Remaining Actions",
        "Skip remaining actions",
        "This causes all remaining actions in the trigger to be skipped.",
        "If / Then / Else, Multiple Functions",
        "If (All Conditions are True) then do (Then Actions) else do (Else Actions)",
        "Add conditions and actions to this function in the main display.",
        "If / Then / Else",
        "\"If \",~Condition,\" then do \",~Action,\" else do \",~Action",
        "",
        "\"For Each Integer A, Do Multiple Actions",
        "For each (Integer A) from \",~Start,\" to \",~End,\", do (Actions)",
        "Add actions to this function in the main display. The end value is assumed to be larger than the start value.",
        "\"For Each Integer B, Do Multiple Actions",
        "For each (Integer B) from \",~Start,\" to \",~End,\", do (Actions)",
        "Add actions to this function in the main display. The end value is assumed to be larger than the start value.",
        "\"For Each Integer Variable, Do Multiple Actions",
        "For each (Integer \",~Variable,\") from \",~Start,\" to \",~End,\", do (Actions)",
        "Add actions to this function in the main display. The end value is assumed to be larger than the start value.",
        "For Each Integer A, Do Action",
        "\"For each (Integer A) from \",~Start,\" to \",~End,\", do \",~Action",
        "The end value is assumed to be larger than the start value.",
        "For Each Integer B, Do Action",
        "\"For each (Integer B) from \",~Start,\" to \",~End,\", do \",~Action",
        "The end value is assumed to be larger than the start value.",
        "For Each Integer Variable, Do Action",
        "\"For each (Integer \",~Variable,\") from \",~Start,\" to \",~End,\", do \",~Action",
        "The end value is assumed to be larger than the start value.",
        "Start Melee AI Script",
        "\"Start melee AI script for \",~Player,\": \",~Script",
        "This should only only be used for computer-controlled player slots.  When using this action, it is advised that you enable the 'Fixed Player Settings' force property.",
        "Start Campaign AI Script",
        "\"Start campaign AI script for \",~Player,\": \",~Script",
        "This should only only be used for computer-controlled player slots.  When using this action, it is advised that you enable the 'Fixed Player Settings' force property.",
        "Send AI Command",
        "Send \",~Player,\" the AI Command (\",~Command,\", \",~Data,\")",
        "This action is for internal use in AI scripts.",
        "Ignore Unit Guard Position",
        "Ignore \",~Unit,\"'s guard position",
        "This action tells the AI to neither use nor replace a given preplaced unit.  This has no effect on Heroes and peon-type units.",
        "Ignore All Unit Guard Positions",
        "Ignore the guard positions of all \",~Player,\" units",
        "This action tells the AI for the given player to neither use nor replace any of its preplaced units.  This has no effect on Heroes and peon-type units.",
        "Recycle Unit Guard Position",
        "Recycle \",~Unit,\"'s guard position",
        "This action requests that the AI recycle the guard position that once belonged to the specified unit.",
        "Lock Guard Position",
        "\"Lock guard position of \",~Unit",
        "This action prevents the AI from changing the guard position of a unit.",
        "Play Unit Animation",
        "Play \",~Unit,\"'s \",~Animation Name,\" animation",
        "Use 'Reset Unit Animation' to revert to a unit's normal animation.",
        "Play Unit Animation (Specify Rarity)",
        "Play \",~Unit,\"'s \",~Animation Name,\" animation, using only \",~Rarity,\" animations",
        "This animation will repeat until reset with 'Reset Unit Animation'.",
        "Queue Unit Animation",
        "Queue \",~Unit,\"'s \",~Animation Name,\" animation",
        "",
        "Reset Unit Animation",
        "Reset \",~Unit,\"'s animation",
        "Sets the unit's animation back to whatever the unit is doing.",
        "Add/Remove Unit Animation Tag",
        "~Add/Remove,\" the \",~Tag,\" animation tag to \",~Unit",
        "",
        "Lock Body-Part Facing",
        "Lock \",~Unit,\"'s \",~Source,\" to face \",~Unit,\", offset by (\",~X,\", \",~Y,\", \",~Z,\")",
        "The unit's body-part will continue to face the target until 'Reset Body-Part Facing' is used.  The offset is taken as (X, Y, Z) from the target's feet.",
        "Reset Body-Part Facing",
        "Reset \",~Unit,\"'s body-part facing",
        "Returns a unit's body-part facing to normal.",
        "Change Unit Size",
        "Change \",~Unit,\"'s size to (\",~X,\"%, \",~Y,\"%, \",~Z,\"%) of its original size",
        "The scaling values apply to (Length, Width, Height) when viewing a unit head-on.",
        "Change Unit Vertex Coloring",
        "Change \",~Unit,\"'s vertex coloring to (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  Most units default to 100% red, green, and blue, with 0% transparency.  A 100% transparent unit is completely invisible.",
        "Change Unit Animation Speed",
        "Change \",~Unit,\"'s animation speed to \",~Percent,\"% of its original speed",
        "To revert a unit's animation speed to default, set its animation speed to 100%.",
        "Change Unit Turn Speed",
        "\"Change \",~Unit,\" turn speed to \",~Value",
        "A unit's turn speed determines how quickly the unit changes direction.  Turn speed values are expected to be between 0 and 1, with smaller numbers indicating slower turning rates.",
        "Change Unit Blend Time",
        "\"Change \",~Unit,\" blend time to \",~Value",
        "A unit's blend time determines how quickly the unit's body parts turn to face a direction.",
        "Change Unit Flying Height",
        "\"Change \",~Unit,\" flying height to \",~Height,\" at \",~Rate",
        "Only flying units use flying heights.",
        "Change Unit Prop Window Angle",
        "\"Change \",~Unit,\" prop window angle to \",~Angle",
        "",
        "Play Destructible Animation",
        "Play \",~Destructible,\"'s \",~Animation Name,\" animation",
        "",
        "Queue Destructible Animation",
        "Queue \",~Destructible,\"'s \",~Animation Name,\" animation",
        "",
        "Change Destructible Animation Speed",
        "Change \",~Destructible,\"'s animation speed to \",~Percent,\"% of its original speed",
        "To revert a destructible's animation speed to default, set its animation speed to 100%.",
        "Play Animation For Doodads In Region",
        "\"Play the \",~Animation Name,\" animation for all doodads of type \",~Doodad Type,\" within \",~Rect",
        "Special animation names: 'show', 'hide', 'soundon', 'soundoff'",
        "Play Animation For Doodads In Circle",
        "\"Play the \",~Animation Name,\" animation for all doodads of type \",~Doodad Type,\" within \",~Radius,\" of \",~Point",
        "Special animation names: 'show', 'hide', 'soundon', 'soundoff'",
        "Apply Camera Object (Timed)",
        "\",~Apply Method,\" \",~Camera Object,\" for \",~Player,\" over \",~Time,\" seconds",
        "",
        "Pan Camera (Timed)",
        "Pan camera for \",~Player,\" to \",~Point,\" over \",~Time,\" seconds",
        "",
        "Pan Camera With Interpolated Height (Timed)",
        "Pan camera for \",~Player,\" to \",~Point,\" with height \",~Z,\" above the terrain over \",~Time,\" seconds",
        "The camera will not drop below the terrain height during its camera path.",
        "Pan Camera As Necessary (Timed)",
        "Pan camera as necessary for \",~Player,\" to \",~Point,\" over \",~Time,\" seconds",
        "If the camera is very far from the destination, it will snap instead of pan.  If the camera is very close to the destination, the pan request will be skipped.",
        "Set Camera Field (Timed)",
        "Set \",~Player,\"'s camera \",~Field,\" to \",~Value,\" over \",~Time,\" seconds",
        "",
        "Rotate Camera Around Point",
        "Rotate camera \",~Angle,\" degrees around \",~Point,\" for \",~Player,\" over \",~Time,\" seconds",
        "",
        "Lock Camera Target To Unit",
        "\"Lock camera target for \",~Player,\" to \",~Unit,\", offset by (\",~X,\", \",~Y,\") using \",~Rotation Source",
        "The camera target is offset by (X, Y) from the center of the unit's feet.",
        "Lock Camera Orientation To Unit",
        "Lock camera orientation for \",~Player,\" to \",~Unit,\", offset by (\",~X,\", \",~Y,\")",
        "",
        "Play Cinematic Camera",
        "Run camera for \",~Player,\" through \",~Camera File,\" cinematic camera",
        "",
        "Stop Camera",
        "\"Stop the camera for \",~Player",
        "",
        "Reset Game Camera",
        "Reset camera for \",~Player,\" to standard game-view over \",~Time,\" seconds",
        "",
        "Change Camera Smoothing Factor",
        "\"Change camera smoothing factor to \",~Factor",
        "",
        "Reset Camera Smoothing Factor",
        "Reset camera smoothing factor",
        "",
        "Sway Camera Source",
        "\"Sway the camera source for \",~Player,\" with magnitude \",~Magnitude,\" and velocity \",~Velocity",
        "This constantly sways the camera source until it is reset with 'Camera - Reset Game Camera' or 'Camera - Stop Swaying Camera'.",
        "Sway Camera Target",
        "\"Sway the camera target for \",~Player,\" with magnitude \",~Magnitude,\" and velocity \",~Velocity",
        "This constantly sways the camera target until it is reset with 'Camera - Reset Game Camera' or 'Camera - Stop Swaying Camera'.",
        "Shake Camera",
        "\"Shake the camera for \",~Player,\" with magnitude \",~Magnitude",
        "This constantly shakes the camera until it is reset with 'Camera - Reset Game Camera' or 'Camera - Stop Swaying/Shaking Camera'.",
        "Stop Swaying/Shaking Camera",
        "\"Stop swaying/shaking the camera for \",~Player",
        "This stops the camera from swaying after a 'Camera - Sway Camera' or 'Camera - Shake Camera' action is used.",
        "Extend/Shrink Camera Bounds",
        "~Extend/Shrink,\" the camera bounds for \",~Player,\" west by \",~West,\", east by \",~East,\", north by \",~North,\", and south by \",~South",
        "",
        "Set Camera Bounds",
        "\"Set the camera bounds for \",~Player,\" to \",~Region",
        "This restricts the game camera to the specified region.  Changing the camera bounds does not change the scale of the minimap.  This should only be called while the camera is facing north.",
        "Set Spacebar-Point",
        "\"Set a spacebar-point for \",~Player,\" at \",~Point",
        "A spacebar-point is a location that the game camera jumps to when the player presses the spacebar.",
        "Transmission From Unit",
        "\"Send transmission to \",~Player Group,\" from \",~Unit,\" named \",~Name,\": Play \",~Sound,\" and display \",~Message,\".  Modify duration: \",~Method,\" \",~Time,\" seconds and \",~Wait/Don't Wait",
        "The duration of 'No sound' is 5 seconds.",
        "Transmission From Unit-Type",
        "\"Send transmission to \",~Player Group,\" from a \",~Player,\" \",~Unit-Type,\" named \",~Name,\" at \",~Point,\": Play \",~Sound,\" and display \",~Message,\".  Modify duration: \",~Method,\" \",~Time,\" seconds and \",~Wait/Don't Wait",
        "The duration of 'No sound' is 5 seconds.",
        "Subtitle Display Override",
        "\"Turn subtitle display override \",~On/Off",
        "Turning this on will cause transmission text to be displayed on the screen even if the user normally has subtitles turned off.",
        "Cinematic Mode",
        "\"Turn cinematic mode \",~On/Off,\" for \",~Player Group",
        "",
        "Cinematic Mode (Timed)",
        "Turn cinematic mode \",~On/Off,\" for \",~Player Group,\" over \",~Time,\" seconds",
        "",
        "Fade Filter",
        "~Fade Type,\" over \",~Duration,\" seconds using texture \",~Texture,\" and color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency\"",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Advanced Filter",
        "Apply a filter over \",~Duration,\" seconds using \",~Blending Method,\" on texture \",~Texture,\", starting with color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) and \",~Transparency,\"% transparency and ending with color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) and \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Show/Hide Filter",
        "~Show/Hide,\" filter\"",
        "",
        "Ping Minimap",
        "Ping minimap for \",~Player Group,\" at \",~Point,\" for \",~Duration,\" seconds",
        "",
        "Ping Minimap With Color",
        "Ping minimap for \",~Player Group,\" at \",~Point,\" for \",~Duration,\" seconds, using a \",~Style,\" ping of color (\"~Red,\"%, \",~Green,\"%, \",~Blue,\"%)",
        "The color values are (Red, Green, Blue).  Warning pings are always red.",
        "Flash Speech Indicator For Unit",
        "Flash a speech indicator for \",~Unit,\" of color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Flash Speech Indicator For Destructible",
        "Flash a speech indicator for \",~Destructible,\" of color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Flash Speech Indicator For Item",
        "Flash a speech indicator for \",~Item,\" of color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Clear Text Messages",
        "\"Clear the screen of text messages for \",~Player Group",
        "",
        "Letterbox Mode On",
        "Turn on letterbox mode (hide interface) for \",~Player Group,\": fade out over \",~Duration,\" seconds",
        "Puts the camera into letterbox mode, hiding the game interface.",
        "Letterbox Mode Off",
        "Turn off letterbox mode (show interface) for \",~Player Group,\": fade in over \",~Duration,\" seconds",
        "Puts the camera into normal (non-letterbox) mode, displaying the game interface.",
        "Disable User Control",
        "\"Disable user control for \",~Player Group",
        "",
        "Enable User Control",
        "\"Enable user control for \",~Player Group",
        "",
        "Enable/Disable Occlusion",
        "~Enable/Disable,\" occlusion for \",~Player Group",
        "When occlusion is enabled, trees that block vision of units become transparent.",
        "Enable/Disable Boundary Tinting",
        "~Enable/Disable,\" boundary tinting for \",~Player Group",
        "",
        "Start Timer",
        "Start \",~Timer,\" as a \",~One-Shot/Repeating,\" timer that will expire in \",~Time,\" seconds",
        "",
        "Pause Timer",
        "~Pause/Resume,\" \",~Timer",
