        "Create Timer Window",
        "\"Create a timer window for \",~Timer,\" with title \",~Title",
        "Timer Windows cannot be displayed at map initialization.",
        "Destroy Timer Window",
        "\"Destroy \",~Timer Window",
        "",
        "Show/Hide Timer Window For Player",
        "~Show/Hide,\" \",~Timer Window,\" for \",~Player",
        "Timer Windows cannot be displayed at map initialization.",
        "Show/Hide Timer Window",
        "~Show/Hide,\" \",~Timer Window",
        "Timer Windows cannot be displayed at map initialization.",
        "Change Timer Window Title",
        "\"Change the title of \",~Timer Window,\" to \",~Title",
        "",
        "Change Timer Window Title Color",
        "Change the color of the title for \",~Timer Window,\" to (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Change Timer Window Time Color",
        "Change the color of the time for \",~Timer Window,\" to (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Create",
        "\"Create a \",~Destructible-Type,\" at \",~Point,\" facing \",~Direction,\" with scale \",~Scale,\" and variation \",~Variation",
        "The facing angle is expected in degrees, with 0 being east and 90 being north.  Use 'Last Created Destructible' to refer to this destructible.",
        "Create (Dead)",
        "\"Create a dead \",~Destructible-Type,\" at \",~Point,\" facing \",~Direction,\" with scale \",~Scale,\" and variation \",~Variation",
        "The facing angle is expected in degrees, with 0 being east and 90 being north.  Use 'Last Created Destructible' to refer to this destructible.",
        "Kill",
        "\"Kill \",~Destructible",
        "",
        "Remove",
        "\"Remove \",~Destructible",
        "",
        "Resurrect",
        "Resurrect \",~Destructible,\" with \",~Value,\" life and \",~Show/Hide,\" birth animation",
        "",
        "Show/Hide",
        "~Show/Hide,\" \",~Destructible",
        "Hidden destructibles are not displayed, but still affect pathing and visibility.",
