        "~Open/Close,\" \",~Walls,\" of \",~Elevator",
        "",
        "Set Elevator Height",
        "\"Set height of \",~Elevator,\" to \",~Height",
        "",
        "Make Invulnerable/Vulnerable",
        "\"Make \",~Destructible,\" \",~Invulnerable/Vulnerable",
        "",
        "Set Occlusion Height",
        "\"Set the occlusion height of \",~Destructible,\" to \",~Height",
        "",
        "Pick Every Destructible In Region And Do Multiple Actions",
        "Pick every destructible in \",~Region,\" and do (Actions)",
        "Use 'Picked Destructible' to refer each destructible as it is picked.  This works for every destructible in the region, including dead destructibles.  Wait actions should not be used within this function.  Add actions to this function in the main display.",
        "Pick Every Destructible In Circle And Do Multiple Actions",
        "Pick every destructible within \",~Radius,\" of \",~Point,\" and do (Actions)",
        "Use 'Picked Destructible' to refer each destructible as it is picked.  This works for every destructible in the region, including dead destructibles.  Wait actions should not be used within this function.  Add actions to this function in the main display.",
        "Pick Every Destructible In Region And Do Action",
        "\"Pick every destructible in \",~Region,\" and do \",~Action",
        "Use 'Picked Destructible' to refer each destructible as it is picked.  This works for every destructible in the region, including dead destructibles.  Wait actions should not be used within this function.",
        "Pick Every Destructible In Circle And Do Action",
        "\"Pick every destructible within \",~Radius,\" of \",~Point,\" and do \",~Action",
        "Use 'Picked Destructible' to refer each destructible as it is picked.  This works for every destructible in the region, including dead destructibles.  Wait actions should not be used within this function.",
        "Show/Hide",
        "~Show/Hide,\" \",~Dialog,\" for \",~Player",
        "Dialogs cannot be displayed at map initialization.",
        "Change Title",
        "\"Change the title of \",~Dialog,\" to \",~Title",
        "",
        "Create Dialog Button",
        "\"Create a dialog button for \",~Dialog,\" labelled \",~Text",
        "",
        "Clear",
        "\"Clear \",~Dialog",
        "This clears the title and all buttons for the specified dialog.",
        "Create Weather Effect",
        "\"Create at \",~Region,\" the weather effect \",~Weather Id",
        "",
        "Enable/Disable Weather Effect",
        "\"Turn \",~Weather Effect,\" \",~On/Off",
        "You can create weather effects via the 'Environment - Create Weather Effect' action.",
        "Remove Weather Effect",
        "\"Remove \",~Weather Effect",
        "",
        "Create Terrain Deformation: Crater",
        "\"Create a \",~Duration,\" second \",~Type,\" crater deformation at \",~Point,\" with radius \",~Radius,\" and depth \",~Depth",
        "Use 'Last Created Terrain Deformation' to refer to this terrain deformation.  Depth may be negative for bumps.  Permanent deformations are not preserved in saved game files.",
        "Create Terrain Deformation: Ripple",
        "Create a \",~Duration,\" second \",~Type,\" ripple deformation at \",~Point,\" with starting radius \",~Radius,\", ending radius \",~Radius,\", and depth \",~Depth,\", using \",~Time,\" second ripples spaced \",~Distance,\" apart",
        "Use 'Last Created Terrain Deformation' to refer to this terrain deformation.",
        "Create Terrain Deformation: Wave",
        "Create a \",~Duration,\" second wave deformation from \",~Source,\" to \",~Target,\" with radius \",~Radius,\", depth \",~Depth,\", and a \",~Delay,\" second trailing delay",
        "Use 'Last Created Terrain Deformation' to refer to this terrain deformation.  Depth may be negative for bumps.",
        "Create Terrain Deformation: Random",
        "Create a \",~Duration,\" second random deformation at \",~Point,\" with radius \",~Radius,\", using depths between \",~Minimum,\" and \",~Maximum,\", updating every \",~Update Interval,\" seconds",
        "Use 'Last Created Terrain Deformation' to refer to this terrain deformation.",
        "Stop Terrain Deformation",
        "Stop \",~Terrain Deformation,\" over \",~Duration,\" seconds",
        "The deformation will smoothly reduce to nothing over the duration.",
        "Stop All Terrain Deformations",
        "Stop all active terrain deformations instantly",
        "This includes any terrain deformations indirectly caused by spells or abilities.",
        "Turn Water Deformation On/Off",
        "\"Turn water deformation \",~On/Off",
        "When this is turned on, terrain deformations will also apply to any water above the terrain.  This does not work with permanent deformations.",
        "Change Terrain Type",
        "\"Change terrain type at \",~Location,\" to \",~Terrain Type,\" using variation \",~Variation,\" in an area of size \",~Area,\" and shape \",~Shape",
        "Use a variation of -1 to generate random variations across the area.",
        "Turn Terrain Pathing On/Off",
        "\"Set terrain pathing at \",~Location,\" of type \",~Pathing,\" to \",~On/Off",
        "Turning pathing on causes the pathing cell to become pathable to the given type.  For example, turning 'Buildability' on makes the pathing cell buildable.  This only affects pathing restrictions caused by terrain (not doodads, units, etc.).",
        "Set Water Tinting Color",
        "Change water tinting color to (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  100% transparent water is completely invisible.",
        "Set Sky",
        "\"Set sky to \",~Sky",
        "",
        "Set Fog",
        "Set fog to style \",~Style,\", z-start \",~Z-Start,\", z-end \",~Z-End,\", density \",~Density,\" and color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%)",
        "The color values are (Red, Green, Blue).",
        "Reset Fog",
        "Reset fog to default values",
        "",
        "Create/Remove Blight Region",
        "~Create/Remove,\" Blight for \",~Player,\" across \",~Region",
        "",
        "Create/Remove Blight Circle",
        "~Create/Remove,\" Blight for \",~Player,\" from \",~Point,\" to a radius of \",~Radius",
        "",
        "Create Floating Text At Point",
        "Create floating text that reads \",~Message,\" at \",~Point,\" with Z offset \",~Z,\", using font size \",~Size,\", color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%), and \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.  Use 'Floating Text - Permanent/Expires' to make this floating text temporary.",
        "Create Floating Text Above Unit",
        "Create floating text that reads \",~Message,\" above \",~Unit,\" with Z offset \",~Z,\", using font size \",~Size,\", color (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%), and \",~Transparency,\"% transparency",
        "Floating text created in this manner does not follow the unit's movement.  The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.  Use 'Floating Text - Permanent/Expires' to make this floating text temporary.",
        "Destroy",
        "\"Destroy \",~Floating Text",
        "",
        "Show/Hide",
        "~Show/Hide,\" \",~Floating Text,\" for \",~Player Group",
        "",
        "Set Velocity",
        "Set the velocity of \",~Floating Text,\" to \",~Speed,\" towards \",~Angle,\" degrees",
        "You can only accurately set the velocity of floating text once, when it is first created.  The angle is expected in degrees, with 0 being east and 90 being north.",
        "Change Color",
        "Change the color of \",~Floating Text,\" to (\",~Red,\"%, \",~Green,\"%, \",~Blue,\"%) with \",~Transparency,\"% transparency",
        "The color values are (Red, Green, Blue).  A 100% transparent color is completely invisible.",
        "Change Position To Point",
        "\"Change the position of \",~Floating Text,\" to \",~Point,\" with Z offset \",~Z",
        "",
        "Change Position To Unit",
        "\"Change the position of \",~Floating Text,\" to \",~Unit,\" with Z offset \",~Z",
        "",
        "Change Text",
        "\"Change text of \",~Floating Text,\" to \",~Message,\" using font size \",~Size",
        "",
        "Suspend/Resume",
        "Change \",~Floating Text,\": \",~Enable/Disable,\" suspend state",
        "",
        "Permanent/Expires",
        "Change \",~Floating Text,\": \",~Enable/Disable,\" permanence",
        "",
        "Change Lifespan",
        "Change the lifespan of \",~Floating Text,\" to \",~Time,\" seconds",
        "This does not affect permanent floating text.  This sets the age at which floating text is removed and cleaned up.",
        "Change Fading Age",
        "Change the fading age of \",~Floating Text,\" to \",~Time,\" seconds",
        "This does not affect permanent floating text.  This sets the age at which floating text begins fading.",
        "Change Age",
        "Change the age of \",~Floating Text,\" to \",~Time,\" seconds",
        "This does not affect permanent floating text.",
        "Text Message (Auto-Timed)",
        "\"Display to \",~Player Group,\" the text: \",~Text",
        "The text is shown for an amount of time that automatically increases with the text length.",
        "Text Message (Explicitly Timed)",
        "\"Display to \",~Player Group,\" for \",~Time,\" seconds the text: \",~Text",
        "",
        "Pause Game",
        "Pause the game",
        "",
        "Unpause Game",
        "Unpause the game",
        "",
        "Set Game Speed",
        "\"Set game speed to \",~Speed",
        "You can lock the game speed with the 'Game - Lock Game Speed' trigger action.",
        "Lock Game Speed",
        "Lock the game speed",
        "This prevents the game speed from being modified.  Not even triggers can modify the game speed when it is locked.",
        "Unlock Game Speed",
        "Unlock the game speed",
        "This allows the game speed to be modified again after a 'Game - Lock Game Speed' action is used.",
        "Set Map Flag",
        "\"Set \",~Map Flag,\" to \",~On/Off",
        "",
        "Set Time Of Day",
        "\"Set the time of day to \",~Time",
        "A game day is 24 hours long.  Six a.m. is 6.00, and six p.m. is 18.00.",
        "Set Time Of Day Speed",
        "Set time of day speed to \",~Percent,\"% of the default speed",
        "Use 100% to revert the speed to normal.",
        "Turn Day/Night Cycle On/Off",
        "\"Turn the day/night cycle \",~On/Off",
        "",
        "Share Vision And Full Unit Control With Team",
        "Grant shared vision and full shared unit control of \",~Player,\" units with his/her allies",
        "Two players are considered allies if they are both allied with each other.",
        "Give Units To Neutral Victim",
        "Give all \",~Player,\" units to the Neutral Victim player",
        "By default, the Neutral Victim player treats all other players as allies, but is treated as an enemy by all other players.",
        "Set Next Level",
        "\"Set the next level to \",~Level",
        "This sets a level to be started after the current game ends.",
        "Victory",
        "Victory \",~Player,\" (\",~Show/Skip,\" dialogs, \",~Show/Skip,\" scores)",
        "",
