        "Load \",~Filename,\" (\",~Show/Skip,\" scores)",
        "",
        "Save Game And Load Game",
        "Save game as \",~Filename,\" and load \",~Filename,\" (\",~Show/Skip,\" scores)",
        "",
        "Save Game And Change Level",
        "Save game as \",~Filename,\" and change level to \",~Filename,\" (\",~Show/Skip,\" scores)",
        "",
        "Rename Saved-Game Folder",
        "\"Rename the \",~Folder,\" saved-game folder to \",~Folder",
        "",
        "Delete Saved-Game Folder",
        "Delete the \",~Folder,\" saved-game folder",
        "This deletes the specified saved-game folder and all of its contents.",
        "Copy Saved-Game",
        "\"Create a copy of the \",~Filename,\" saved-game and name it \",~Filename",
        "This action only works in response to Game Load and Game Save events, and can only be used up to 16 times per event.",
        "Set Campaign Screen",
        "\"Set campaign to \",~Campaign",
        "",
