        "",
        "Show/Hide Custom Campaign Button",
        "~Show/Hide,\" custom campaign button \",~Number",
        "",
        "Set Ally Color Filter",
        "\"Set ally color filtering to \",~State",
        "A value of 0 disables filtering.  A value of 1 enables filtering for the minimap.  A value of 2 enables filtering for the minimap and the game view.",
        "Show/Hide Creep Camps On Minimap",
        "~Show/Hide,\" creep camps on the minimap\"",
        "",
        "Enable/Disable Minimap Buttons",
        "~Enable/Disable,\" ally color button and \",~Enable/Disable,\" creep camp button\"",
        "",
        "Enable/Disable Selection",
        "~Enable/Disable,\" selection and deselection functionality (\",~Enable/Disable,\" selection circles)\"",
        "Objects can still be selected and deselected via trigger actions.  Disabling selection prevents drag-selection as well.  Selection circles are only displayed if selection is enabled.",
        "Enable/Disable Drag-Selection",
        "~Enable/Disable,\" drag-selection functionality (\",~Enable/Disable,\" drag-selection box)\"",
        "",
        "Enable/Disable Pre-Selection",
        "~Enable/Disable,\" pre-selection functionality (\",~Enable/Disable,\" pre-selection circles, life bars, and object info)\"",
