        "\"Preload all files listed in \",~Filename",
        "",
        "Create Game Cache",
        "\"Create a game cache from \",~Filename",
        "A game cache allows you to store data between maps, or between games on a given map.  If the specified file does not exist, it will be created.",
        "Save Game Cache",
        "\"Save \",~Game Cache",
        "Saves the game cache, using the same filename from which it was created.",
        "Store Unit",
        "\"Store \",~Unit,\" as \",~Label,\" of \",~Category,\" in \",~Game Cache",
        "Use the 'Game Cache - Restore Unit' actions to load this unit from a cache.  Label and Category names should not contain spaces.",
        "Store Real",
        "\"Store \",~Value,\" as \",~Label,\" of \",~Category,\" in \",~Game Cache",
        "Use the 'Game Cache - Load Real Value' function to load this value from a cache.  Label and Category names should not contain spaces.",
        "Store Integer",
        "\"Store \",~Value,\" as \",~Label,\" of \",~Category,\" in \",~Game Cache",
        "Use the 'Game Cache - Load Integer Value' function to load this value from a cache.  Label and Category names should not contain spaces.",
        "Store Boolean",
        "\"Store \",~Value,\" as \",~Label,\" of \",~Category,\" in \",~Game Cache",
        "Use the 'Game Cache - Load Boolean Value' function to load this value from a cache.  Label and Category names should not contain spaces.",
        "Store String",
        "\"Store \",~Value,\" as \",~Label,\" of \",~Category,\" in \",~Game Cache",
        "Use the 'Game Cache - Load String Value' function to load this value from a cache.  Label and Category names should not contain spaces.",
        "Restore Unit Facing Angle",
        "\"Restore \",~Label,\" of \",~Category,\" from \",~Game Cache,\" for \",~Player,\" at \",~Location,\" facing \",~Angle",
        "Use 'Last Restored Unit' to refer to the unit created by this action.  If the label is not found, no unit will be created, and 'Last Restored Unit' will have the value 'No Unit'.",
        "Restore Unit Facing Point",
        "\"Restore \",~Label,\" of \",~Category,\" from \",~Game Cache,\" for \",~Player,\" at \",~Location,\" facing \",~Point",
        "Use 'Last Restored Unit' to refer to the unit created by this action.  If the label is not found, no unit will be created, and 'Last Restored Unit' will have the value 'No Unit'.",
        "Reload All",
        "Reload all game cache data from disk",
        "",
        "Clear Game Cache",
        "\"Clear \",~Game Cache",
        "Clears all labels of all categories in a game cache.",
        "Clear Category",
        "\"Clear all labels of \",~Category,\" in \",~Game Cache",
        "Clears all labels of a specific category in a game cache.",
        "Create Hashtable",
