        "\"Turn on \",~Trigger",
        "Allows the trigger to be executed.",
        "Run (Checking Conditions)",
        "Run \",~Trigger,\" (checking conditions)",
        "Runs the trigger's actions if its conditions are true.",
        "Run (Ignoring Conditions)",
        "Run \",~Trigger,\" (ignoring conditions)",
        "Runs the trigger's actions while ignoring events and conditions.",
        "Add To Trigger Queue",
        "Add \",~Trigger,\" to the trigger queue (\",~Checking/Ignoring,\" conditions)",
        "Triggers added to the trigger queue are executed one at a time, in turn.  Triggers added in this manner should remove themselves using 'Trigger - Remove From Queue'.",
        "Remove From Trigger Queue",
        "Remove \",~Trigger,\" from the trigger queue",
        "If a trigger is already running via the trigger queue, removing it will allow the next trigger in the trigger queue to run, but will not stop the trigger itself from finishing its execution.",
        "Clear Trigger Queue",
        "Clear the trigger queue",
        "This will remove all triggers from the trigger queue.",
        "Clear Trigger Queue Of Pending Triggers",
        "Clear all pending triggers from the trigger queue",
        "This will remove all pending triggers from the trigger queue.  If a trigger is currently running in the queue, it will not be removed.",
        "Add New Event",
        "\"Add to \",~Trigger,\" the event \",~Event",
        "",
        "Create Units Facing Angle",
        "Create \",~Number,\" \",~Unit,\" for \",~Player,\" at \",~Point,\" facing \",~Direction,\" degrees",
        "The facing angle is expected in degrees, with 0 being east and 90 being north.  Use 'Last Created Unit Group' to refer to these created units.  Use 'Last Created Unit' to refer to exactly one of these units.",
        "Create Units Facing Point",
        "\"Create \",~Number,\" \",~Unit,\" for \",~Player,\" at \",~Point,\" facing \",~Point",
        "Use 'Last Created Unit Group' to refer to these created units.  Use 'Last Created Unit' to refer to exactly one of these units.",
        "Create Corpse",
        "\"Create a \",~Unit,\" corpse for \",~Player,\" at \",~Point",
        "Not all units have corpse forms.  Use 'Last Created Unit' to refer to this unit.",
        "Create Permanent Corpse",
        "Create a permanent \",~Style,\" \",~Unit,\" corpse for \",~Player,\" at \",~Point,\" facing \",~Direction,\" degrees",
        "Fleshy corpses will often appear skeletal for the first 8 seconds of their existence.",
        "Kill",
        "\"Kill \",~Unit",
        "",
        "Remove",
        "Remove \",~Unit,\" from the game",
        "Leaves no corpse.  If used on a Hero, that Hero cannot be resurrected.",
        "Explode",
        "\"Explode \",~Unit",
        "",
        "Replace",
        "Replace \",~Unit,\" with a \",~Unit-Type,\" using \",~Property Usage,\" life and mana",
        "Use 'Last Replaced Unit' to refer to the replacement unit.  Note that any variables referring to the old unit will need to be updated.  Replacing a Haunted Gold Mine will usually yield a normal Gold Mine in addition to the replacement unit.",
        "Hide",
        "\"Hide \",~Unit",
        "Use the 'Unhide Unit' action to show a unit.  Hidden units do not show up in 'Units In Region' queries.",
        "Unhide",
        "\"Unhide \",~Unit",
        "Use the 'Hide Unit' action to hide a unit.  Hidden units do not show up in 'Units In Region' queries.",
        "Change Color",
        "\"Change color of \",~Unit,\" to \",~Color",
        "Changing a unit's color does not change the unit's ownership.",
        "Change Owner",
        "\"Change ownership of \",~Unit,\" to \",~Player,\" and \",~Change/Retain Color",
        "",
        "Shared Vision",
        "~Grant/Deny,\" shared vision of \",~Unit,\" to \",~Player",
        "Note that neutral player slots cannot share their vision.",
        "Move Unit (Instantly)",
        "\"Move \",~Unit,\" instantly to \",~Point",
        "",
        "Move Unit And Face Angle (Instantly)",
        "Move \",~Unit,\" instantly to \",~Point,\", facing \",~Direction,\" degrees",
        "The facing angle is expected in degrees, with 0 being east and 90 being north.",
        "Move Unit And Face Point (Instantly)",
        "\"Move \",~Unit,\" instantly to \",~Point,\", facing \",~Point",
