        "",
        "Make Invulnerable/Vulnerable",
        "\"Make \",~Unit,\" \",~Invulnerable/Vulnerable",
        "",
        "Pause/Unpause",
        "~Pause/Unpause,\" \",~Unit",
        "A paused unit stops and performs no orders, but remembers its orders and continues them upon being unpaused.",
        "Pause/Unpause All Units",
        "~Pause/Unpause,\" all units\"",
        "A paused unit stops and performs no orders, but remembers its orders and continues them upon being unpaused.  This action only affects units that exist when this action is run.",
        "Pause/Unpause Expiration Timer",
        "~Pause/Unpause,\" the expiration timer for \",~Unit",
        "Only summoned units have expiration timers.",
        "Add Expiration Timer",
        "\"Add a \",~Duration,\" second \",~Buff Type,\" expiration timer to \",~Unit",
        "",
        "Make Unit Explode On Death",
        "Make \",~Unit,\" \",~Explode/Die Normally,\" on death",
        "",
        "Suspend Corpse Decay",
        "~Suspend/Resume,\" corpse decay for \",~Unit",
        "This only works on corpses, and only after the corpses' death animations have finished.",
        "Reset Ability Cooldowns",
        "\"Reset ability cooldowns for \",~Unit",
        "This makes all of the unit's abilities available for use again almost immediately.",
        "Set Building Construction Progress",
        "Set \",~Building,\" construction progress to \",~Progress,\"%",
        "This should only be used on buildings that are currently under construction.",
        "Set Building Upgrade Progress",
        "Set \",~Building,\" upgrade progress to \",~Progress,\"%",
        "This should only be used on buildings that are currently being upgraded.  This does not affect research-based upgrades.",
        "Make Unit Sleep",
        "Make \",~Unit,\" \",~Sleep/Remain Awake,\" when unprovoked",
        "Units owned by players 1 through 12 never sleep.",
        "Make Unit Sleep At Night",
        "Make \",~Unit,\" \",~Sleep/Remain Awake,\" when unprovoked at night",
        "Units owned by players 1 through 12 never sleep.",
        "Wake Up",
        "\"Wake up \",~Unit",
        "This affects nocturnal sleep, not magical sleep.",
        "Turn Alarm Generation On/Off",
        "\"Turn alarm generation for \",~Unit,\" \",~On/Off",
        "This only affects buildings.",
        "Rescue Unit",
        "\"Rescue \",~Unit,\" for \",~Player,\" and \",~Change/Retain Color",
        "",
        "Make Rescuable",
        "\"Make \",~Unit,\" \",~Rescuable/Unrescuable,\" by \",~Player Group",
        "",
        "Set Rescue Range",
        "\"Limit rescue events for \",~Unit,\" to a range of \",~Range",
        "To make a unit rescuable, use 'Unit - Make Rescuable' or set the unit's owner to 'Rescuable'.",
        "Set Rescue Behavior For Units",
        "Make units \",~Change/Retain Color,\" when rescued",
        "By default, units owned by 'Rescuable' players do not change color when rescued.  This action does not affect units that have already been rescued.",
        "Set Rescue Behavior For Buildings",
        "Make buildings \",~Change/Retain Color,\" when rescued",
        "By default, buildings owned by 'Rescuable' players change color when rescued.  This action does not affect buildings that have already been rescued.",
        "Enable/Disable Supply Usage",
        "~Enable/Disable,\" supply usage for \",~Unit",
        "",
        "Make Unit Face Unit",
        "Make \",~Unit,\" face \",~Unit,\" over \",~Time,\" seconds",
        "Forces a unit to face another unit.  This only works if the source unit is not moving at the time.",
        "Make Unit Face Point",
        "Make \",~Unit,\" face \",~Point,\" over \",~Time,\" seconds",
        "Forces a unit to face a point.  This only works if the source unit is not moving at the time.",
        "Make Unit Face Angle",
        "Make \",~Unit,\" face \",~Angle,\" over \",~Time,\" seconds",
        "Forces a unit to face a directional angle, expected in degrees, with 0 being east.  This only works if the source unit is not moving at the time.",
        "Set Movement Speed",
        "\"Set \",~Unit,\" movement speed to \",~Speed",
        "Common movement speeds range from 150 to 300.",
        "Turn Collision On/Off",
        "\"Turn collision for \",~Unit,\" \",~On/Off",
        "Collision-disabled units ignore obstacles, but are still themselves treated as obstacles.",
        "Set Acquisition Range",
        "\"Set \",~Unit,\" acquisition range to \",~Range",
        "The acquisition range of a unit is the distance at which the unit acquires targets to attack.",
        "Set Custom Value",
        "\"Set the custom value of \",~Unit,\" to \",~Index",
        "Custom values are only used in triggers, and can be used to store any integer value.",
        "Remove Buffs",
        "\"Remove \",~Buff Type,\" buffs from \",~Unit",
        "",
        "Remove Buffs By Type",
        "Remove \",~Buff Type,\" buffs considered \",~Buff Resist,\" from \",~Unit,\" (\",~Include/Exclude,\" expiration timers, \",~Include/Exclude,\" auras)",
        "",
        "Remove Specific Buff",
        "\"Remove \",~Buff,\" buff from \",~Unit",
        "",
        "Add Ability",
        "\"Add \",~Ability,\" to \",~Unit",
        "",
        "Remove Ability",
        "\"Remove \",~Ability,\" from \",~Unit",
        "In most cases, removing an ability in this manner is permanent.",
        "Add Classification",
        "\"Add classification of \",~Classification,\" to \",~Unit",
        "The info panel for a selected unit won't update until the unit is re-selected.",
        "Remove Classification",
        "\"Remove classification of \",~Classification,\" from \",~Unit",
        "The info panel for a selected unit won't update until the unit is re-selected.",
        "Issue Order Targeting A Unit",
        "\"Order \",~Unit,\" to \",~Order,\" \",~Unit",
