        "\"Order \",~Unit,\" to build a \",~Unit-Type,\" at \",~Point",
        "",
        "Issue Train/Upgrade Order",
        "\"Order \",~Unit,\" to train/upgrade to a \",~Unit-Type",
        "This action can be used to order a unit to upgrade itself.  A Town Hall, for example, can be upgraded by ordering it to train a Keep.",
        "Issue Research Order",
        "\"Order \",~Unit,\" to research \",~Tech-Type",
        "Weapons and armor upgrades can be researched multiple times via this trigger action.",
        "Issue Drop Item Order",
        "\"Order \",~Unit,\" to drop \",~Item,\" at \",~Point",
        "",
        "Issue Move Item In Inventory Order",
        "\"Order \",~Unit,\" to move \",~Item,\" to inventory slot \",~Index",
        "This only works if the unit is already carrying the item.  If an item exists in the slot, the items will be swapped.",
        "Issue Give Item Order",
        "\"Order \",~Unit,\" to give \",~Item,\" to \",~Unit",
        "",
        "Damage Area",
        "\"Cause \",~Unit,\" to damage circular area after \",~Seconds,\" seconds of radius \",~Size,\" at \",~Location,\", dealing \",~Amount,\" damage of attack type \",~AttackType,\" and damage type \",~DamageType",
        "This does not interrupt the unit's orders.  The source unit gets credit for kills resulting from this damage.",
        "Damage Target",
        "\"Cause \",~Unit,\" to damage \",~Target,\", dealing \",~Amount,\" damage of attack type \",~AttackType,\" and damage type \",~DamageType",
        "This does not interrupt the unit's orders.  The source unit gets credit for kills resulting from this damage.",
        "Decrease Level Of Ability For Unit",
        "\"Decrease level of \",~Ability,\" for \",~Unit",
        "If the unit does not have the ability, this does nothing.",
        "Increase Level Of Ability For Unit",
        "\"Increase level of \",~Ability,\" for \",~Unit",
        "If the unit does not have the ability, this does nothing.",
        "Set Level Of Ability For Unit",
        "\"Set level of \",~Ability,\" for \",~Unit,\" to \",~Level",
        "If the unit does not have the ability, this does nothing.",
        "Pick Every Unit In Unit Group And Do Multiple Actions",
        "Pick every unit in \",~Unit Group,\" and do (Actions)",
        "Use 'Picked Unit' to refer each unit as it is picked.  This works for every unit in the group, including dead units.  Wait actions should not be used within this function.  Add actions to this function in the main display.",
        "Pick Every Unit In Unit Group And Do Action",
        "\"Pick every unit in \",~Unit Group,\" and do \",~Action",
        "Use 'Picked Unit' to refer each unit as it is picked.  This works for every unit in the group, including dead units.  Wait actions should not be used within this function.",
        "Add Unit",
        "\"Add \",~Unit,\" to \",~Unit Group",
        "This adds a unit to a Unit Group variable.  This does not affect the unit itself.",
        "Add Unit Group",
        "\"Add all units of \",~Unit Group,\" to \",~Unit Group",
        "This adds all units of a unit group to a Unit Group variable.  This does not affect the units themselves.",
        "Remove Unit",
        "\"Remove \",~Unit,\" from \",~Unit Group",
        "This removes a unit from a Unit Group variable.  This does not affect the unit itself.",
        "Remove Unit Group",
        "\"Remove all units of \",~Unit Group,\" from \",~Unit Group",
        "This removes all units of a unit group from a Unit Group variable.  This does not affect the units themselves.",
        "Clear",
        "\"Remove all units from \",~Unit Group",
        "This removes all units from a Unit Group variable.  This does not affect the units themselves.",
        "Issue Order Targeting A Unit",
        "\"Order \",~Unit Group,\" to \",~Order,\" \",~Unit",
        "This will issue an order to at most 12 units from the specified unit group.  Note that 'Right-Click' orders issued this way do not always behave as they do when issued to units in-game.",
        "Issue Order Targeting A Point",
        "\"Order \",~Unit Group,\" to \",~Order,\" \",~Point",
        "This will issue an order to at most 12 units from the specified unit group.",
        "Issue Order Targeting A Destructible",
        "\"Order \",~Unit Group,\" to \",~Order,\" \",~Destructible",
        "This will issue an order to at most 12 units from the specified unit group.",
        "Issue Order Targeting An Item",
        "\"Order \",~Unit Group,\" to \",~Order,\" \",~Item",
        "This will issue an order to at most 12 units from the specified unit group.",
        "Issue Order With No Target",
        "\"Order \",~Unit Group,\" to \",~Order",
        "This will issue an order to at most 12 units from the specified unit group.",
        "Issue Train Order",
        "\"Order \",~Unit Group,\" to train a \",~Unit-Type",
        "This action can also be used to order a unit to upgrade itself.  A Town Hall, for example, can be upgraded by ordering it to train a Keep.  This will issue an order to at most 12 units from the specified unit group.",
